INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(29301, '1 Peter 3:10', '1 Peter', 3, 10, '&nbsp;ځکه چې، ”کۀ تاسو د ژوند سره مينه کوئ او ښې ورځې ليدل غواړئ، نو په خپلې ژبې بد مۀ وايئ او په خپلو شونډو دروغ مۀ وايئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29302, '1 Peter 3:11', '1 Peter', 3, 11, '&nbsp;ښۀ کوئ او د بدو نه ځان ساتئ، امن قائم ساتئ او د هغې کوشش کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29303, '1 Peter 3:12', '1 Peter', 3, 12, '&nbsp;ځکه چې د مالِک خُدائ نظر په صادقانو وى او د هغوئ فريادونه اورى. خو مالِک خُدائ د هغوئ په خلاف وى څوک چې بد کارونه کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29304, '1 Peter 3:13', '1 Peter', 3, 13, '&nbsp;نو بيا تاسو له څوک نقصان درکولے شى کۀ چرې تاسو د نېک کارونو خواهشمند يئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29305, '1 Peter 3:14', '1 Peter', 3, 14, '&nbsp;خو کۀ چرې تاسو د صداقت دپاره مصيبتونه هم وزغمئ، تاسو له به برکت درکړے شى نو ځکه د هغوئ په يرولو مۀ يرېږئ او زړونه مۀ بائيلئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29306, '1 Peter 3:15', '1 Peter', 3, 15, '&nbsp;بلکې په خپلو زړونو کښې مسيح مقدس مالِک وګڼئ، او هغوئ ته د جواب ورکولو دپاره همېشه تيار اوسئ څوک چې ستاسو نه ستاسو د اُميد د وجې تپوس وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29307, '1 Peter 3:16', '1 Peter', 3, 16, '&nbsp;خو په نرمۍ او درناوى سره خپل ضمير صفا ساتئ نو چې څوک په مسيح کښې ستاسو ښۀ چال چلن ته کنځل کوى نو هغوئ به بيا په داسې کولو پښېمانه شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29308, '1 Peter 3:17', '1 Peter', 3, 17, '&nbsp;نو دا بهتره ده چې مونږ د ښو کارونو دپاره تکليف وزغمو، چې د خُدائ پاک د مرضۍ دپاره وى، نه چې د شرارت دپاره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29309, '1 Peter 3:18', '1 Peter', 3, 18, '&nbsp;ځکه چې مسيح ستاسو د ګناهونو دپاره يو ځل د همېشه دپاره مړ شو، يعنې صادق د ګناهګارانو دپاره، د دې دپاره چې تاسو خُدائ پاک له راولى. هغه په جسمانى توګه مړ کړے شو خو په روحانى توګه ژوندے کړے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29310, '1 Peter 3:19', '1 Peter', 3, 19, '&nbsp;هم دغه شان هغه لاړو او قېد روحونو ته يې پېغام ورکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29311, '1 Peter 3:20', '1 Peter', 3, 20, '&nbsp;دا هغه روحونه وُو چې په پخوا زمانه کښې نافرمانه وُو کله چې خُدائ پاک د نوح په زمانه کښې صبر او انتظار کولو چې کله هغۀ لا کشتۍ جوړوله نو چې په کښې اتۀ کسان د سېلاب نه بچ پاتې شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29312, '1 Peter 3:21', '1 Peter', 3, 21, '&nbsp;او دا اوبۀ د دې بپتسمې په مثال دى چې اوس تاسو بچ کوى، د دې مقصد ګندګى لرې کول نۀ دى بلکې په دې مونږ خُدائ پاک نه خواست کوُو چې د عيسىٰ مسيح د بيا ژوندى کېدو په وسيله زمونږ ضميرونه پاک کړى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29313, '1 Peter 3:22', '1 Peter', 3, 22, '&nbsp;څوک چې آسمان ته ختلے دے او د خُدائ پاک ښى لاس ته ناست دے، او فرښتې، اختيارمند او قُدرتونو والا يې د هغۀ تابع کړې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29314, '1 Peter 4:1', '1 Peter', 4, 1, '&nbsp;نو بيا چې مسيح په جسمانى توګه مصيبت وزغملو نو تاسو هم د مسيح غوندې طبيعت خپل کړئ، ځکه چا چې درد او مصيبت وزغملو هغه د ګناه د قبضې نه آزاد شو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29315, '1 Peter 4:2', '1 Peter', 4, 2, '&nbsp;نو چې تاسو خپل نور پاتې دُنياوى ژوند په انسانى خواهشونو تېر نۀ کړئ بلکې د خُدائ پاک د مرضۍ په مطابق يې تېر کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29316, '1 Peter 4:3', '1 Peter', 4, 3, '&nbsp;ځکه چې تاسو خپل کافى ژوند پخوا په هغه څۀ کښې تېر کړے دے څۀ ته چې د بې‌دينه کار وئيلے وو يعنې په عياشۍ، شهوت پرستۍ، مستۍ، په نشه، په ګډا نچا او په ناروا بُت پرستۍ تېر کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29317, '1 Peter 4:4', '1 Peter', 4, 4, '&nbsp;هغوئ په دې حېران دى چې تاسو نور د هغوئ سره په هغه خرابه ګندګۍ کښې ملګرتيا نۀ کوئ نو ځکه تاسو ته بدرد وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29318, '1 Peter 4:5', '1 Peter', 4, 5, '&nbsp;خو هغوئ به د دې حساب خُدائ پاک له ورکوى څوک چې د ژوندو او د مړو عدالت کولو ته تيار دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29319, '1 Peter 4:6', '1 Peter', 4, 6, '&nbsp;نو هغه دا چې زيرے هغوئ ته هم اورولے شوے وو څوک چې اوس مړۀ دى چې په جسمانى توګه د هغوئ هم هغه شان اِنصاف وکړے شى لکه څنګه چې د نورو خلقو کيږى چې په روحانى توګه داسې ژوندى پاتې شى لکه چې خُدائ پاک دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29320, '1 Peter 4:7', '1 Peter', 4, 7, '&nbsp;د ټولو څيزونو خاتمه رانزدې ده، نو په دې وجه خپل ځان ساتئ او د دُعا کولو دپاره په هوش کښې اوسئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29321, '1 Peter 4:8', '1 Peter', 4, 8, '&nbsp;د ټولو نه لويه خبره دا ده چې په خپلو کښې يو بل سره ډېره مينه کوئ ځکه چې مينه په ډېرو ګناهونو پړده اچوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29322, '1 Peter 4:9', '1 Peter', 4, 9, '&nbsp;د شکايت نه بغېر په خپلو کښې د يو بل مېلمستيا کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29323, '1 Peter 4:10', '1 Peter', 4, 10, '&nbsp;تاسو هر يو ته خُدائ پاک د خپل روحانى لوئې خزانې نه جدا جدا نعمت درکړے دے. هغه په خپلو کښې د يو بل په خدمت کښې په ښۀ طريقه استعمال کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29324, '1 Peter 4:11', '1 Peter', 4, 11, '&nbsp;کۀ څوک څۀ پېغام ورکوى نو داسې وينا دې وکړى لکه څنګه چې د خُدائ پاک کلام دے، کۀ څوک خِدمت کوى نو د هغه طاقت په مطابق دې کوى کوم چې خُدائ پاک ورکړے وى، نو د دې دپاره چې په ټولو خبرو کښې د عيسىٰ مسيح په وسيله د خُدائ پاک جلال ظاهر شى. جلال او بادشاهى تل تر تله هم د هغۀ ده، آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29325, '1 Peter 4:12', '1 Peter', 4, 12, '&nbsp;زما خوږو ملګرو، کوم د مصيبت اور چې ستاسو د آزمېښت دپاره په تاسو کښې بل دے، نو په هغې حېرانېږئ مه چې په مونږ دا عجيبه شان خبره راغلې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29326, '1 Peter 4:13', '1 Peter', 4, 13, '&nbsp;بلکې خوشحالى کوئ چې تاسو د مسيح په مصيبتونو کښې شريک شوئ، نو چې تاسو هم خوشحالى وکړئ او د خوشحالۍ نه چغې کړئ کله چې د هغۀ جلال ظاهر شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29327, '1 Peter 4:14', '1 Peter', 4, 14, '&nbsp;کۀ تاسو ته د مسيح د نوم په وجه بدرد ووئيلے شى نو تاسو بختور يئ، ځکه چې د جلال روح، يعنې د خُدائ پاک روح په تاسو سورے کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29328, '1 Peter 4:15', '1 Peter', 4, 15, '&nbsp;خو په تاسو کښې دې څوک قاتل، غل، بدکاره يا د نورو په کار کښې د لاس وهلو په وجه مصيبت ونۀ زغمى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29329, '1 Peter 4:16', '1 Peter', 4, 16, '&nbsp;اوس کۀ په تاسو کښې څوک د مسيحى په توګه تکليف وزغمى، نو هغه دې دا شرم نۀ ګڼى، بلکې د دې نوم په وجه دې د خُدائ پاک ثنا ووائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29330, '1 Peter 4:17', '1 Peter', 4, 17, '&nbsp;ځکه چې د عدالت وخت راغلے دے چې د خُدائ پاک د کوره به شروع شى، او کۀ دا زمونږ نه شروع شى نو د هغوئ به څۀ حال وى څوک چې د خُدائ پاک زيرے نۀ منى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29331, '1 Peter 4:18', '1 Peter', 4, 18, '&nbsp;او، ”کۀ صادق په مشکله خلاصون مومى نو د بې‌دينه او ګناه ګار به څۀ حال وى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29332, '1 Peter 4:19', '1 Peter', 4, 19, '&nbsp;نو بيا څوک چې په دې وجه د خُدائ پاک د مرضۍ په مطابق مصيبتونه زغمى، هغوئ دې خپل ځانونه وفادار خالق ته په حواله کړى او همېشه دې نېکى کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29333, '1 Peter 5:1', '1 Peter', 5, 1, '&nbsp;په تاسو کښې چې کوم مشران دى، زۀ هم د هغوئ په شان مشر او د مسيح د مصيبتونو ګواه او په ښکاره کېدونکى جلال کښې شريک يم، او تاسو ته دا خواست کوم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29334, '1 Peter 5:2', '1 Peter', 5, 2, '&nbsp;چې د خُدائ پاک د هغه رمې شپونتوب کوئ چې خُدائ تاسو له درکړې ده. دا خدمت د مجبورۍ د مخه مۀ کوئ بلکې د خُدائ پاک د مرضۍ په مطابق په خوشحالۍ سره يې کوئ، او د ناجائزې ګټې دپاره نه، بلکې د زړۀ په شوق سره يې کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29335, '1 Peter 5:3', '1 Peter', 5, 3, '&nbsp;او کوم خلق چې ستاسو په حواله شوى دى، په هغوئ رُعب داب مۀ اچوئ بلکې د رمې دپاره نمونه شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29336, '1 Peter 5:4', '1 Peter', 5, 4, '&nbsp;او کله چې مشر شپونکے څرګند شى نو تاسو له به د جلال تاج درکړے شى چې کله به هم نۀ مړاوے کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29337, '1 Peter 5:5', '1 Peter', 5, 5, '&nbsp;اے ځوانانو، هم دغه شان تاسو هم د مشرانو تابعدار اوسئ، بلکې د يو بل د خِدمت دپاره تاسو ټول په حليمۍ ملا وتړئ ځکه چې، ”خُدائ پاک د کبرژنو مقابله کوى خو عاجزانو له فضل ورکوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29338, '1 Peter 5:6', '1 Peter', 5, 6, '&nbsp;نو په دې وجه د خُدائ پاک د مضبوط لاس لاندې په عاجزۍ اوسېږئ نو چې هغه تاسو له په وخت عزت درکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29339, '1 Peter 5:7', '1 Peter', 5, 7, '&nbsp;او خپله ټوله پرېشانى په هغۀ واچوئ ځکه چې هغه ستاسو خيال ساتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29340, '1 Peter 5:8', '1 Peter', 5, 8, '&nbsp;تاسو ځان ساتئ او بېدار اوسئ ځکه چې ستاسو مخالف اِبليس لکه د غړمبېدونکى ازمرى په شان په دې لټون کښې دے چې څوک ژوندے تېر کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29341, '1 Peter 5:9', '1 Peter', 5, 9, '&nbsp;تاسو ايمان کښې مضبوط شئ او د هغۀ مقابله وکړئ ځکه چې تاسو ته معلومه ده چې په ټوله دُنيا کښې ستاسو وروڼه او خوېندې هم دغه شان مصيبتونه زغمى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29342, '1 Peter 5:10', '1 Peter', 5, 10, '&nbsp;د لږ وخت د مصيبت زغملو نه وروستو به د هر قسمه فضل ورکوونکى خُدائ پاک چا چې تاسو په مسيح کښې د خپل جلال دپاره رابللى يئ، هغه به په خپله تاسو بحال کړى، مدد به مو وکړى، قوت به درکړى او مضبوط به مو کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29343, '1 Peter 5:11', '1 Peter', 5, 11, '&nbsp;د هغۀ قدرت دې تل تر تله وى، آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29344, '1 Peter 5:12', '1 Peter', 5, 12, '&nbsp;ما د سيلوانوس په وسيله چې زۀ يې ايماندار ورور ګڼم دا ورکوټے خط وليکلو چې تاسو له تسلى درکړم او د دې خبرې ګواهى وکړم چې دا د خُدائ پاک حقيقى فضل دے او په دې قائم پاتې شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29345, '1 Peter 5:13', '1 Peter', 5, 13, '&nbsp;هغه جماعت چې په بابل کښې دے او تاسو سره يو ځائ غوره شوے دے، هغه او زما زوئ مرقوس تاسو ته سلام وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29346, '1 Peter 5:14', '1 Peter', 5, 14, '&nbsp;يو بل ته په پاکې مينې سره سلام کوئ. په تاسو ټولو دې سلامتى وى څوک چې په مسيح کښې يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29347, '2 Peter 1:1', '2 Peter', 1, 1, '&nbsp;د شمعون پطروس د طرف نه چې د عيسىٰ مسيح غلام او رسول دے، د هغه خلقو په نوم چې زمونږ د خُدائ پاک او د خلاصوونکى عيسىٰ مسيح په صداقت کښې يې زمونږ په شان قيمتى ايمان موندلے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29348, '2 Peter 1:2', '2 Peter', 1, 2, '&nbsp;زمونږ د خُدائ پاک او مالِک عيسىٰ د پېژندګلو په وجه دې په تاسو ډېر ډېر فضل او سلامتى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29349, '2 Peter 1:3', '2 Peter', 1, 3, '&nbsp;خُدائ پاک د خپل الٰهى قُدرت په وسيله مونږ له هر هغه څۀ راکړل کوم چې د ديندارۍ ژوندون تېرولو دپاره ضرورى دى. دا هر څۀ مونږ ته د هغۀ د پېژندګلو په وجه راکړے شوى دى، يعنې هغه چا چې مونږ د خپل خاص جلال او نېکۍ په وسيله راوبللو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29350, '2 Peter 1:4', '2 Peter', 1, 4, '&nbsp;او هم د دې په وسيله هغۀ مونږ سره خپلې قيمتى او ډيرې لوئې وعدې وکړې، د دې دپاره چې تاسو د هغۀ په الاهى فطرت کښې شريک شئ نو چې تاسو د هغه خرابو کارونو نه بچ شئ کوم چې د دې دُنيا په وجه پېدا کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29351, '2 Peter 1:5', '2 Peter', 1, 5, '&nbsp;په دې وجه تاسو خپل پوره کوشش وکړئ چې په خپل ايمان کښې نېکى زياته کړئ، او په نېکۍ کښې عِلم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
