(29353, '2 Peter 1:7', '2 Peter', 1, 7, '&nbsp;او په ديندارۍ کښې ورورولى عزيزولى، او په ورورولۍ او عزيزولۍ کښې مينه زياته کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29354, '2 Peter 1:8', '2 Peter', 1, 8, '&nbsp;ځکه کۀ دا خبرې په تاسو کښې وى او زياتيږى نو دا تاسو زمونږ د مالِک عيسىٰ مسيح په پېژندګلو کښې بې‌کاره او بې‌مېوې کېدو نه بچ کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29355, '2 Peter 1:9', '2 Peter', 1, 9, '&nbsp;خو په چا کښې چې دا خويونه نۀ وى، نو د هغۀ نظر دومره کم دے چې ړندېدو ته نزدې دے او د خپلو وړومبو ګناهونو نه پاک کېدل يې هېر کړى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29356, '2 Peter 1:10', '2 Peter', 1, 10, '&nbsp;نو په دې وجه اے وروڼو او خوېندو، د خپلې بلنې او غوره والى د ثابتولو زيات کوشش کوئ، ځکه کۀ تاسو داسې اخلاق ساتئ نو هيڅکله به تيندک ونۀ خورئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29357, '2 Peter 1:11', '2 Peter', 1, 11, '&nbsp;په دې طريقه د دې سره به تاسو زمونږ د مالِک او خلاصوونکى عيسىٰ مسيح په ابدى بادشاهۍ کښې ډېر په عزت سره داخل کړے شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29358, '2 Peter 1:12', '2 Peter', 1, 12, '&nbsp;په دې وجه به زۀ تاسو ته همېشه دا خبرې دريادوم، اګر کۀ تاسو د مخکښې نه د دې نه خبر يئ او په هغه حق خبرې قائم يئ چې تاسو ته وئيلے شوې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29359, '2 Peter 1:13', '2 Peter', 1, 13, '&nbsp;او ترڅو چې زۀ ژوندے يم، تاسو ته په دريادولو او پارولو دا خبره په خپل ځان ضرورى ګڼم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29360, '2 Peter 1:14', '2 Peter', 1, 14, '&nbsp;ما ته پته ده چې زما د مرګ وخت رانزدې دے ځکه چې زمونږ مالِک عيسىٰ مسيح ما ته ښکاره وئيلى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29361, '2 Peter 1:15', '2 Peter', 1, 15, '&nbsp;او زۀ به خپل پوره کوشش کوم چې زما د مرګ نه پس به تاسو ته همېشه دا خبرې يادې وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29362, '2 Peter 1:16', '2 Peter', 1, 16, '&nbsp;ځکه چې مونږ په هغه قيصو پسې نه ځو چې په چالاکۍ سره جوړې شوې دى کله چې مونږ تاسو د خپل مالِک عيسىٰ مسيح د قدرت او د راتلو په حقله خبر کړئ، بلکې مونږ د هغۀ جلال په خپلو سترګو ليدلے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29363, '2 Peter 1:17', '2 Peter', 1, 17, '&nbsp;کله چې هغۀ ته د خُدائ پلار عزت او جلال حاصل شو نو ورته د هغه بهتر جلال نه آواز راغلو چې، ”دا زما محبوب زوئ دے د چا نه چې زۀ راضى يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29364, '2 Peter 1:18', '2 Peter', 1, 18, '&nbsp;مونږ په خپله دا آواز د آسمان نه واورېدو، کله چې مونږ د هغۀ سره په مقدس غرۀ باندې وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29365, '2 Peter 1:19', '2 Peter', 1, 19, '&nbsp;نو مونږ سره د نبوت هغه کلام دے چې ډېر معتبر دے، دا به تاسو ښۀ وکړئ چې په دې داسې غور وکړئ لکه چې ډيوه په يو تيارۀ ځائ کښې رڼا ورکوى، ترڅو چې سحر شى او د سبا ستورى ستاسو په زړونو کښې وځليږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29366, '2 Peter 1:20', '2 Peter', 1, 20, '&nbsp;خو د هر څۀ نه اول تاسو ته په دې خبره پوهېدل په کار دى چې د کِتاب مقدس يوه پېشګوئې هم د نبى خپل سوچ نۀ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29367, '2 Peter 1:21', '2 Peter', 1, 21, '&nbsp;ځکه چې يوه پېشګوئې هم کله د بنى آدم په خپله رضا نۀ ده نازله شوې، بلکې بنى آدمو د روحُ القُدس په وجه د خُدائ پاک د طرف نه خبرې کولې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29368, '2 Peter 2:1', '2 Peter', 2, 1, '&nbsp;خو څنګه چې په بنى اِسرائيلو کښې د دروغو نبيان راوچت شوى وُو، هم دغه شان به په تاسو کښې د دروغو اُستاذان راوچت شى. هغوئ به په پټه هلاکوونکى بدعتونه راوباسى او هغوئ به د هغه مالِک نه اِنکار وکړى چا چې د هغوئ فديه ورکړې ده، او په خپلو ځانونو به زر هلاکت راولى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29369, '2 Peter 2:2', '2 Peter', 2, 2, '&nbsp;نو بيا ډېر به د خپلې شهوت پرستۍ په لار روان شى او د دې اُستاذانو په وجه به د حق د لارې بدنامى کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29370, '2 Peter 2:3', '2 Peter', 2, 3, '&nbsp;او په خپل لالچ کښې به هغوئ د دروغو په قيصو ستاسو نه ناجائزه ګټې واخلى. د هغوئ په خلاف د سزا حکم د ډېر مخکښې نه شوے دے او د هغوئ تباهى رانزدې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29371, '2 Peter 2:4', '2 Peter', 2, 4, '&nbsp;نو بيا خُدائ پاک فرښتې پرې نۀ ښودې کله چې هغوئ ګناه وکړه بلکې هغوئ يې په دوزخ کښې واچولې او په تورو تيارو کندو کښې يې په زنځيرونو وتړلې چې د قيامت د ورځې پورې به هلته وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29372, '2 Peter 2:5', '2 Peter', 2, 5, '&nbsp;نو بيا هغۀ تېره شوې دُنيا پرې نۀ ښوده او په بې‌دينه خلقو يې سېلاب راوستو خو صرف د صداقت پېغمبر نوح او ورسره يې نور اووۀ کسان بچ کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29373, '2 Peter 2:6', '2 Peter', 2, 6, '&nbsp;او هغۀ د سدوم او عموره ښارونه تباه کړل او وې سيزل او ايره يې کړل، او د راتلونکې زمانې د بې‌دينو دپاره يې د عبرت مقام وګرځولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29374, '2 Peter 2:7', '2 Peter', 2, 7, '&nbsp;ځکه هغۀ لوط هم بچ کړو چې صادق انسان وو کله چې هغه د بې‌دينه خلقو د ناپاک چال چلن نه ډېر تنګ شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29375, '2 Peter 2:8', '2 Peter', 2, 8, '&nbsp;هغه يو صادق انسان چې په هغوئ کښې اوسېدلو هره ورځ د هغه صادق ژوند د هغوئ د بې‌شرعې کارونو د ليدلو او اورېدلو په وجه په عذابېدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29376, '2 Peter 2:9', '2 Peter', 2, 9, '&nbsp;نو مالِک پوهيږى چې څنګه دينداران د آزمېښت نه بچ کړى او بدکاران د عدالت تر ورځې پورې په سزا کښې وساتى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29377, '2 Peter 2:10', '2 Peter', 2, 10, '&nbsp;خو خاص هغوئ څوک چې جسمانى ناپاکو خواهشونو پسې ګرځى او څوک چې د خُدائ پاک اختيار سپک ګڼى، دوئ ګستاخه او مغروره دى او په جلالى هستيانو باندې په بدو وئيلو دوئ نۀ شرميږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29378, '2 Peter 2:11', '2 Peter', 2, 11, '&nbsp;سره د دې چې فرښتې اګر کۀ په طاقت او په قُدرت کښې د هغوئ نه لوئې دى، د مالِک په وړاندې د هغوئ خلاف د بدرد وئيلو اِلزام نۀ لګوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29379, '2 Peter 2:12', '2 Peter', 2, 12, '&nbsp;خو دا خلق د ځنګلى مخلوق په شان دى چې بې‌ضميره دى او د رانيولو او هلاکولو دپاره پېدا شوى دى. د کومو خبرو په حقله چې ناخبره دى، د هغوئ په حقله په نورو بدرد وائى، هغوئ به د ځنګلى ځناورو په شان هلاک کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29380, '2 Peter 2:13', '2 Peter', 2, 13, '&nbsp;کوم نقصان چې هغوئ نورو له ورکړے دے د هغې سزا به ورته مِلاو شى. هغوئ ته په رڼا ورځ عياشى کول خوند ورکوى، هغوئ بې‌عزته او بې‌شرمه دى. هغوئ د خپلې دوکه بازۍ نه مزه اخلى کۀ څۀ هم تاسو سره په يو دسترخوان خوراک څښاک کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29381, '2 Peter 2:14', '2 Peter', 2, 14, '&nbsp;هغوئ ښځو ته د زنا کارۍ په سترګو ګورى او د ګناه نه نۀ شى اوړېدے، هغوئ کمزورى خلق راګېروى، د هغوئ زړونه په حرص آموخته شوى دى، هغوئ لعنتيان دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29382, '2 Peter 2:15', '2 Peter', 2, 15, '&nbsp;هغوئ نېغه لاره پرېښودله، او بې‌لارې شوى دى او د بعور د زوئ بلعام په لار روان دى چا چې ناحقه ګټه ښۀ وګڼله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29383, '2 Peter 2:16', '2 Peter', 2, 16, '&nbsp;خو هغه په خپل قصور ملامته شو چې يوې بې‌ژبې خرې د انسان په شان خبرې وکړې او نبى يې د ليونتوب نه منع کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29384, '2 Peter 2:17', '2 Peter', 2, 17, '&nbsp;دغه د دروغو اُستاذان لکه اوچ کُوهيان دى او لکه د داسې وريځې په شان دى چې سيلۍ يې وړى راوړى، نو د هغوئ دپاره تک تور ځائ ساتلے شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29385, '2 Peter 2:18', '2 Peter', 2, 18, '&nbsp;ځکه چې هغوئ د کبر او بېهوده خبرې کوى، او د شهوت پرستۍ په وسيله هغه خلق په جسمانى خواهشونو کښې راګېروى څوک چې لږ څۀ کښې د هغه چا نه راتښتېدلى دى چې په ګمراهۍ کښې ژوند تېروى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29386, '2 Peter 2:19', '2 Peter', 2, 19, '&nbsp;هغوئ د خلقو سره د آزادۍ لوظ کوى خو هغوئ په خپله د ګمراهۍ غلامان دى، ځکه چې خلق هم د هغه څۀ غلامان وى د څۀ نه چې مجبور وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
