(29388, '2 Peter 2:21', '2 Peter', 2, 21, '&nbsp;نو بيا د هغوئ دپاره به دا ښۀ وه چې چرې هم هغوئ د صداقت لار پېژندلے نۀ وے هسې نه چې د پېژندلو نه وروستو يې هغه حُکم رد کړى کوم چې ورته د صادقه ژوند تېرولو دپاره ورکړے شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29389, '2 Peter 2:22', '2 Peter', 2, 22, '&nbsp;او په هغوئ دا متل ثابتيږى چې، ”سپے د خپل قى په طرف راګرځى،“ او ”خنزير د لامبلو نه وروستو بيا په خټو کښې رغړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29390, '2 Peter 3:1', '2 Peter', 3, 1, '&nbsp;ګرانو دوستانو، دا زما دوېم خط دے چې تاسو ته يې ليکم. په دواړو کښې زۀ ستاسو صفا زړونه راپاروم او درته يادګيرنه کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29391, '2 Peter 3:2', '2 Peter', 3, 2, '&nbsp;زۀ غواړم چې تاسو هغه پېشګويانې رايادې کړئ چې پاکو نبيانو مخکښې کړى دى او د مالِک او خلاصوونکى هغه حُکم ياد ساتئ چې تاسو ته ستاسو د رسولانو په وسيله درکړے شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29392, '2 Peter 3:3', '2 Peter', 3, 3, '&nbsp;تاسو ته د ټولو نه اول په دې ځان پوهول په کار دى چې په آخرو ورځو کښې به داسې ټوقماران راشى چې مسخرې به کوى او د خپلو خواهشاتو په مطابق به چليږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29393, '2 Peter 3:4', '2 Peter', 3, 4, '&nbsp;او وائى به چې، ”د هغۀ د راتلو وعده څۀ شوه؟ ځکه چې د کله نه چې زمونږ پلار نيکۀ مړۀ شوى دى د هغه وخت نه تر اوسه پورې هر څۀ هم هغه شان دى لکه چې د مخلوق د شروع نه وُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29394, '2 Peter 3:5', '2 Peter', 3, 5, '&nbsp;هغوئ خو قصداً دا حقيقت هېروى چې د خُدائ پاک د کلام په وسيله آسمانونه د ډېر پخوا نه پېدا شوى دى، او زمکه د اوبو نه جوړه ده او د اوبو په وسيله پېدا شوې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29395, '2 Peter 3:6', '2 Peter', 3, 6, '&nbsp;نو بيا هم د دغه اوبو په وسيله د هغه تېر وخت دُنيا غرقه او هلاکه شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29396, '2 Peter 3:7', '2 Peter', 3, 7, '&nbsp;خو په هم هغه کلام کوم آسمانونه او زمکه چې اوس موجود دى د کلام په وسيله په اور کښې د سوزولو دپاره وساتلے شول، او دا به د بې‌دينه خلقو د عدالت او هلاکت تر ورځې پورې محفوظ وساتلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29397, '2 Peter 3:8', '2 Peter', 3, 8, '&nbsp;خو زما ملګرو، دا حقيقت دې ستاسو نه هېر نۀ شى چې د مالِک په نزد يوه ورځ د زرو کالو برابره ده او زر کاله د يوې ورځې برابر دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29398, '2 Peter 3:9', '2 Peter', 3, 9, '&nbsp;مالِک په خپل لوظ کښې سستى نۀ کوى لکه چې بعضې خلقو ته سستى ښکارى بلکې هغه ستاسو په حقله صبر کوى، او هغه غواړى چې څوک هم هلاک نۀ شى بلکې چې ټول توبه وباسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29399, '2 Peter 3:10', '2 Peter', 3, 10, '&nbsp;خو د مالِک خُدائ د قيامت ورځ به لکه د غل په شان راشى، او په هغه ورځ به آسمانونه ډېر په ګړبړ د نظر نه پناه شى، يعنې ستورى سيارې به د اور په سخت تاو سره ويلى شى، او زمکه او په هغې د بنى آدمو ټول شوى کارونه به ښکاره شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29400, '2 Peter 3:11', '2 Peter', 3, 11, '&nbsp;نو څنګه چې ټول څيزونه په دې طريقه هم ويلى کېدونکى دى نو بيا تاسو ته په پاک چال چلن او په ديندارۍ کښې څنګه ژوند کول په کار دى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');